import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.io.FilterInputStream;
import java.io.BufferedInputStream;
import java.io.InputStream;


public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        ScanReader in = new ScanReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        DTreasureIsland solver = new DTreasureIsland();
        solver.solve(1, in, out);
        out.close();
    }

    static class DTreasureIsland {
        long ans;
        int n;
        int m;
        char[][] arr;

        public void solve(int testNumber, ScanReader in, PrintWriter out) {


            long mod = 1000003379;
            n = in.scanInt();
            m = in.scanInt();
            arr = new char[n][m];
            for (int i = 0; i < n; i++) arr[i] = in.scanString().toCharArray();
            ans = Long.MAX_VALUE;


            long[][] dp = new long[n][m];
            dp[0][0] = 1;
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] == '.') {
                        if (i - 1 >= 0) dp[i][j] = (dp[i][j] + dp[i - 1][j]) % mod;
                        if (j - 1 >= 0) dp[i][j] = (dp[i][j] + dp[i][j - 1]) % mod;
                    }
                }
            }


            long dp2[][] = new long[n][m];
            dp2[n - 1][m - 1] = 1;
            for (int i = n - 1; i >= 0; i--) {
                for (int j = m - 1; j >= 0; j--) {
                    if (arr[i][j] == '.') {
                        if (i + 1 < n) dp2[i][j] = (dp2[i][j] + dp2[i + 1][j]) % mod;
                        if (j + 1 < m) dp2[i][j] = (dp2[i][j] + dp2[i][j + 1]) % mod;
                    }
                }
            }


            if (dp[n - 1][m - 1] == 0) ans = 0;

            if (n == 1 || m == 1) {
                ans = Math.min(ans, 1);
                out.println(ans);
                return;
            }


            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] == '.' && (!(i == 0 && j == 0) && (!(i == n - 1 && j == m - 1)))) {
                        if (dp[n - 1][m - 1] == ((dp[i][j] * dp2[i][j]) % mod)) {
                            ans = Math.min(ans, 1);
                        }
                    }
                }
            }


            if (ans == Long.MAX_VALUE) ans = 2;
            out.println(ans);


        }

    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int INDEX;
        private BufferedInputStream in;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder RESULT = new StringBuilder();
            do {
                RESULT.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return RESULT.toString();
        }

        private boolean isWhiteSpace(int n) {
            if (n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1) return true;
            else return false;
        }

    }
}


