                    if (arr[i][j] == '.') {
                        addPath(dp, i, j, i - 1, j, mod);
                        addPath(dp, i, j, i, j - 1, mod);
                    }
                }
            }
            return dp;
        }

        private long[][] calculatePathsFromBottomRight(long mod) {
            long[][] dp2 = new long[n][m];
            dp2[n - 1][m - 1] = 1;
            for (int i = n - 1; i >= 0; i--) {
                for (int j = m - 1; j >= 0; j--) {
                    if (arr[i][j] == '.') {
                        addPath(dp2, i, j, i + 1, j, mod);
                        addPath(dp2, i, j, i, j + 1, mod);
                    }
                }
            }
            return dp2;
        }

        private void addPath(long[][] dp, int i, int j, int ni, int nj, long mod) {
            if (isValidPosition(ni, nj)) {
                dp[i][j] = (dp[i][j] + dp[ni][nj]) % mod;
            }
        }

        private boolean isValidPosition(int i, int j) {
            return i >= 0 && i < n && j >= 0 && j < m;
        }

        private boolean handleSpecialCases(long[][] dp, PrintWriter out) {
            if (dp[n - 1][m - 1] == 0) {
                ans = 0;
                out.println(ans);
                return true;
            }

            if (n == 1 || m == 1) {
                ans = Math.min(ans, 1);
                out.println(ans);
                return true;
            }

            return false;
        }

        private void findCriticalPoints(long[][] dp, long[][] dp2, long mod) {
            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    if (arr[i][j] == '.' && !isStartOrEnd(i, j)) {
                        if (dp[n - 1][m - 1] == ((dp[i][j] * dp2[i][j]) % mod)) {
                            ans = Math.min(ans, 1);
                        }
                    }
                }
            }
        }

        private boolean isStartOrEnd(int i, int j) {
            return (i == 0 && j == 0) || (i == n - 1 && j == m - 1);
        }

        private void outputResult(PrintWriter out) {
            if (ans == Long.MAX_VALUE) {
                ans = 2;
            }
            out.println(ans);
        }
    }

    static class ScanReader {
        private byte[] buf = new byte[4 * 1024];
        private int INDEX;
        private BufferedInputStream in;
        private int TOTAL;

        public ScanReader(InputStream inputStream) {
            in = new BufferedInputStream(inputStream);
        }

        private int scan() {
            if (INDEX >= TOTAL) {
                INDEX = 0;
                try {
                    TOTAL = in.read(buf);
                } catch (Exception e) {
                    e.printStackTrace();
                }
                if (TOTAL <= 0) return -1;
            }
            return buf[INDEX++];
        }

        public int scanInt() {
            int I = 0;
            int n = scan();
            while (isWhiteSpace(n)) n = scan();
            int neg = 1;
            if (n == '-') {
                neg = -1;
                n = scan();
            }
            while (!isWhiteSpace(n)) {
                if (n >= '0' && n <= '9') {
                    I *= 10;
                    I += n - '0';
                    n = scan();
                }
            }
            return neg * I;
        }

        public String scanString() {
            int c = scan();
            while (isWhiteSpace(c)) c = scan();
            StringBuilder RESULT = new StringBuilder();
            do {
                RESULT.appendCodePoint(c);
                c = scan();
            } while (!isWhiteSpace(c));
            return RESULT.toString();
        }

        private boolean isWhiteSpace(int n) {
            return n == ' ' || n == '\n' || n == '\r' || n == '\t' || n == -1;
        }

    }
